 card.innerHTML=`<div class="cardTop"><span class="region">${names.of(d.code)} · ${typeLabels[d.type]}</span><span class="score">${d.score===null?'Bronprofiel':d.score+'% eigen inschatting'}</span></div><h3><button class="cardTitle" aria-label="${esc(d.name)} — reisdetails openen">${esc(d.name)}</button></h3><div class="badgeStrip">${d.interestEvidence.map(k=>`<span class="status good">${dimensions[k]}: ${k==='duiken'?'rif in bron, toegang controleren':k==='strand'?'kust in bron':'bronvermelding'}</span>`).join('')}</div><p class="cardIntro">${esc(d.description)}</p><div class="facts"><div><strong>${value(c.temp,' °C')}</strong><small>maandgemiddelde · ${months[d.chosenMonth-1]}</small></div><div><strong>${value(c.rain,' mm')}</strong><small>regen per maand</small></div><div><strong>${value(c.sun,' u/dag')}</strong><small>modelzonneschijn</small></div></div><p class="hint">Klimaatreferentie: ${esc(d.climateReference)}${d.climateSource?' · ERA5 2015–2024':''}. Dit is geen landelijk gemiddelde.</p><div class="badgeStrip"><span class="status ${statusClass}">${problems.length?'Buiten een bekende grens':d.unknown.length?'Bekende gegevens meegewogen · deels onbekend':'Geen bekende grens overschreden'}</span>${d.climateSource?'<span class="status good">Klimaatbron beschikbaar</span>':''}</div>${d.itineraryNotes.map(note=>`<p class="durationNote">${esc(note)}</p>`).join('')}<div class="cardHighlights"><strong>Vijf ideeën om te onderzoeken</strong>${d.highlights.length?`<ol>${d.highlights.slice(0,5).map((h,index)=>`<li><button class="textButton highlightButton" data-highlight="${index}">${esc(h.name)}</button><small> · ${({Natural:'natuur',Cultural:'cultuur',Mixed:'natuur & cultuur'})[h.category]||'erfgoed'}</small><p class="highlightBrief">${esc(h.description.split('. ')[0]+'.')}</p></li>`).join('')}</ol>`:'<p class="hint">Nog geen highlights met bron; er kunnen wel interessante activiteiten zijn.</p>'}</div>${problems.length?`<ul class="failureList">${problems.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:''}${d.unknown.length?`<details class="cardIssues"><summary>Onbekende gegevens (${d.unknown.length})</summary><ul>${d.unknown.map(k=>`<li>${esc(failureText({key:k}))}</li>`).join('')}</ul><p>Deze velden sluiten de bestemming niet automatisch uit.</p></details>`:''}`;
