 button('Bekijk details',()=>details(d));button(selected.has(d.id)?'Verwijder uit opgeslagen':'Bewaar bestemming',()=>{selected.has(d.id)?selected.delete(d.id):selected.add(d.id);search();});card.append(actions);target.append(card);
