function matchesText(d){const query=normalizeText($('destinationSearch').value.trim());return !query||normalizeText(`${d.name} ${names.of(d.code)} ${d.highlights.map(h=>h.name).join(' ')}`).includes(query);}
function renderResults(){
 const matches=lastResults.recommendations.filter(matchesText),near=lastResults.near.filter(matchesText),uncertain=lastResults.uncertain.filter(matchesText),outside=lastResults.outside.filter(matchesText),query=$('destinationSearch').value.trim();
 $('count').textContent=`${matches.length} opties · ${uncertain.length} met onbekende velden`;$('cards').replaceChildren();
 if(!matches.length)$('cards').innerHTML='<div class="panel"><h3>Geen opties binnen de bekende grenzen</h3><p>Bekijk waarom bestemmingen afvallen of pas je bekende grenzen aan. De catalogus blijft beschikbaar via Alle landen.</p></div>';
 matches.slice(0,limit).forEach(d=>renderCard(d,$('cards')));$('showMore').hidden=matches.length<=limit;$('showMore').textContent=`Toon meer (${matches.length-limit} resterend)`;
 $('nearCards').replaceChildren();near.slice(0,6).forEach(d=>renderCard(d,$('nearCards'),{near:true}));if(!near.length)$('nearCards').innerHTML='<p class="hint">Geen bijna-passende opties voor deze zoekterm.</p>';
 $('unknownSection').hidden=$('unknownPolicy').value!=='separate';$('unknownCount').textContent=`(${uncertain.length})`;$('unknownCards').replaceChildren();uncertain.slice(0,query?Math.max(24,unknownLimit):unknownLimit).forEach(d=>renderCard(d,$('unknownCards')));
 $('showMoreUnknown').hidden=uncertain.length<=(query?Math.max(24,unknownLimit):unknownLimit);$('outsideSection').hidden=!query;$('outsideCards').replaceChildren();if(query)outside.slice(0,12).forEach(d=>renderCard(d,$('outsideCards')));
 $('searchDiagnosis').hidden=!query;if(query){$('searchDiagnosis').textContent=`“${query}”: ${matches.length} worden meegenomen op bekende gegevens, ${near.length} missen net een grens, ${uncertain.length} hebben nog onbekende velden en ${outside.length} vallen buiten je selectie of zijn een landsoverzicht. Hieronder staat per profiel waarom. Ontbrekende velden tellen niet als een onvoldoende.`;}
 renderCatalog();renderComparison();
}
function renderCatalog(){
 $('catalogCards').replaceChildren();for(const d of currentCatalog().filter(matchesText).slice(0,catalogLimit)){const row=document.createElement('article');row.className='catalogRow';const label=document.createElement('div');label.innerHTML=`<strong>${esc(d.name)}</strong><small>${names.of(d.code)} · ${typeLabels[d.type]} · ${d.geography.subregion} · ${d.climateStatus==='unknown'?'klimaat onbekend':'klimaatbron beschikbaar'}</small>`;const b=document.createElement('button');b.className='secondary';b.textContent='Bekijk';b.addEventListener('click',()=>details(d));row.append(label,b);$('catalogCards').append(row);}$('catalogMore').hidden=currentCatalog().filter(matchesText).length<=catalogLimit;
}
function renderComparison(){
 const f=filters(),all=currentCatalog(),rated=$('compareAll').checked?[...lastResults.recommendations,...lastResults.near].filter(matchesText):all.filter(d=>selected.has(d.id)).map(d=>evaluateDestination(d,f,all));
 $('comparison').replaceChildren();if(!rated.length){$('comparison').textContent='Nog geen bestemmingen om te vergelijken. Bewaar een bestemming of vink alle zoekresultaten aan.';return;}
 const table=document.createElement('table');table.innerHTML='<caption>Vergelijking — onbekend betekent niet ongunstig</caption><thead><tr><th>Bestemming</th><th>Type</th><th>Status</th><th>Interesse</th><th>Prijs p.p.</th><th>Vliegen (u)</th><th>Totaal (u)</th><th>Boot (min)</th><th>Daglicht (u)</th><th>Zonneschijn (u)</th></tr></thead><tbody></tbody>';
 for(const d of rated){const tr=document.createElement('tr');const td=document.createElement('th'),b=document.createElement('button');b.className='textButton';b.textContent=d.name;b.addEventListener('click',()=>details(d));td.append(b);tr.append(td);for(const text of [typeLabels[d.type],({match:'Bekende grenzen passen',unknown:'Nog te controleren',excluded:'Buiten selectie',near:'Bijna passend',outside:'Grens overschreden'})[d.status],d.score===null?'Onbekend':d.score+'% ('+d.confidence+'% beoordeeld)',d.price?money(d.price.perPerson):'Onbekend',value(d.transport?.flightMax),value(d.transport?.totalMax),value(d.transport?.boat?.maxMinutes),value(d.climateSelected.daylight),value(d.climateSelected.sun)]){const cell=document.createElement('td');cell.textContent=text;tr.append(cell);}table.querySelector('tbody').append(tr);}$('comparison').append(table);
}
function activateView(view){activeView=view;for(const key of ['explore','saved','compare','catalog']){$(key+'View').hidden=key!==view;$('tab-'+key).setAttribute('aria-selected',String(key===view));$('tab-'+key).tabIndex=key===view?0:-1;}document.querySelector('.resultViewport').scrollTop=0;renderComparison();store();}
function search(){
 if(!$('filters').checkValidity()){ $('error').textContent='Controleer de ingevulde aantallen en grenswaarden.';return;}
 const f=filters();if(!f.types.length){$('error').textContent='Vink minstens één bestemmingstype aan.';return;}if(!f.months.length){$('error').textContent='Vink minstens één mogelijke reismaand aan.';return;}
 if(Number.isFinite(f.minTemp)&&Number.isFinite(f.maxTemp)&&f.minTemp>f.maxTemp){$('error').textContent='De minimumtemperatuur moet lager zijn dan de maximumtemperatuur.';return;}
 $('error').textContent='';store();lastResults=searchDestinations(currentCatalog(),f);limit=12;unknownLimit=6;
 $('tripSummary').textContent=`${f.people} reizigers · ${f.days} dagen · ${f.months.map(m=>months[m-1]).join(', ')} · ${f.monthMode==='all'?'elke maand moet passen':'één passende maand is genoeg'} · max. ${money(f.budget)} per persoon (${money(f.budget*f.people)} voor de groep)`;
 renderResults();$('savedCards').replaceChildren();const all=currentCatalog(),rated=all.filter(d=>selected.has(d.id)).map(d=>evaluateDestination(d,f,all));
 $('savedCount').textContent=`(${rated.length})`;$('navSavedCount').textContent=String(rated.length);renderComparison();rated.forEach(d=>renderCard(d,$('savedCards')));
 if(activeDetail){const previousScroll=$('detail').scrollTop;details(all.find(d=>d.id===activeDetail),false,true);$('detail').scrollTop=previousScroll;}
 if(!rated.length)$('savedCards').innerHTML='<p class="hint">Bewaar bestemmingen om ze hier te vergelijken. Je bewaarde selectie blijft staan als je filters wijzigt.</p>';
}
$('allMonths').addEventListener('click',()=>{chosenMonths.clear();months.forEach((_,i)=>chosenMonths.add(i+1));$('months').querySelectorAll('input').forEach(x=>x.checked=true);search();});
$('filters').addEventListener('submit',e=>{e.preventDefault();search();});
$('filters').addEventListener('change',e=>{if(e.target.id!=='countrySearch')search();});
$('filters').addEventListener('input',e=>{if(e.target.type==='range'||e.target.type==='number'){clearTimeout(refreshTimer);refreshTimer=setTimeout(search,100);}});
$('countrySearch').addEventListener('input',countries);
$('destinationSearch').addEventListener('input',()=>{limit=12;catalogLimit=60;renderResults();});$('sort').addEventListener('change',search);
$('showMore').addEventListener('click',()=>{limit+=12;renderResults();});$('catalogMore').addEventListener('click',()=>{catalogLimit+=60;renderCatalog();});$('showMoreUnknown').addEventListener('click',()=>{unknownLimit+=12;renderResults();});
$('clearVisited').addEventListener('click',()=>{visited.clear();visitedRegions.clear();countries();search();});
$('close').addEventListener('click',()=>{activeDetail=null;$('detail').classList.remove('isOpen');$('detailBody').innerHTML='<div class="detailEmpty"><h2>Bekijk een bestemming</h2><p>Klik op een resultaat voor reisdetails.</p></div>';store();});
for(const view of ['explore','saved','compare','catalog'])$('tab-'+view).addEventListener('click',()=>activateView(view));
$('compareAll').addEventListener('change',renderComparison);
document.querySelector('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const keys=['explore','saved','compare','catalog'],next=keys[(keys.indexOf(activeView)+(e.key==='ArrowRight'?1:3))%4];activateView(next);$('tab-'+next).focus();});
$('reset').addEventListener('click',()=>{try{localStorage.removeItem('vakantiekompas');}catch{}location.reload();});
$('exportPreferences').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(filters(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vakantiekompas-voorkeuren.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('importPreferences').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw new Error('Bestand is te groot.');const parsed=JSON.parse(await file.text());if(!parsed || typeof parsed!=='object' || Array.isArray(parsed) || !parsed.weights)throw new Error('Geen geldig voorkeurenbestand.');localStorage.setItem('vakantiekompas',JSON.stringify(migrateState(parsed)));location.reload();}catch(error){$('importStatus').textContent='Terugzetten mislukt: '+error.message;}});
window.addEventListener('vakantiekompas:before-update',store);
countries();search();activateView(['explore','saved','compare','catalog'].includes(saved.view)?saved.view:'explore');if(saved.detail&&knownIds.has(saved.detail))details(baseCatalog().find(d=>d.id===saved.detail));

let geographicIndex=null;
for(const code of countryCodes){const option=document.createElement('option');option.value=code;option.textContent=names.of(code);$('geoCountry').append(option);}
async function queryGeography(){
 $('geoStatus').textContent='Geografische databank laden…';
 try{if(!geographicIndex){const response=await fetch(document.querySelector('meta[name="geographic-index"]').content);if(!response.ok)throw new Error('Databank niet bereikbaar');geographicIndex=await response.json();}
 const query=normalizeText($('geoSearch').value.trim()),code=$('geoCountry').value,type=$('geoType').value;
 const rows=(type==='city'?geographicIndex.cities:geographicIndex.regions).filter(row=>countryCodes.includes(row[1])&&(!code||row[1]===code)&&(!query||normalizeText(row[2]).includes(query)));
 $('geoStatus').textContent=rows.length+' gevonden · eerste 50 getoond. Kies een land of specifiekere naam voor meer gerichte resultaten.';$('geoRows').replaceChildren();
 for(const row of rows.slice(0,50)){const element=document.createElement('div');element.className='geoRow';const text=document.createElement('div');text.textContent=row[2];const small=document.createElement('small');small.textContent=names.of(row[1])+' · '+typeLabels[type];text.append(small);const b=document.createElement('button');b.className='secondary';b.textContent='Bekijk & neem mee';b.addEventListener('click',()=>{const generated=profileFromGeography(row,type,names),profile=baseCatalog().find(d=>d.code===generated.code&&d.type===generated.type&&d.geoId===generated.geoId)||generated;if(!knownIds.has(profile.id))extraProfiles.set(profile.id,profile);knownIds.add(profile.id);search();details(profile);});element.append(text,b);$('geoRows').append(element);}
 }catch(error){$('geoStatus').textContent='Laden mislukt: '+error.message;}
}
$('loadGeography').addEventListener('click',queryGeography);$('geoSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();queryGeography();}});
